package com.daniil.wristlens.wear;
import android.content.Context;import android.net.Uri;import android.os.Handler;import android.os.Looper;import android.os.SystemClock;import androidx.annotation.NonNull;import androidx.work.*;import com.daniil.wristlens.shared.*;import com.google.android.gms.tasks.Tasks;import com.google.android.gms.wearable.Wearable;import org.json.*;import java.io.IOException;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLong;
public final class DownloadWorker extends Worker {
 private final Handler main=new Handler(Looper.getMainLooper());private volatile MediaClient client;private String job;
 public DownloadWorker(@NonNull Context c,@NonNull WorkerParameters p){super(c,p);}
 @NonNull public Result doWork(){Context c=getApplicationContext();job=getInputData().getString("job");JSONObject data=Downloads.job(c,job);if(data==null||Downloads.cancelled(c,job))return Result.success();int copied=0;
  try{setForegroundAsync(Downloads.foreground(c,job)).get(10,TimeUnit.SECONDS);String node=data.getString("node");if(Tasks.await(Wearable.getNodeClient(c).getConnectedNodes(),10,TimeUnit.SECONDS).stream().noneMatch(n->n.isNearby()&&n.getId().equals(node)))throw new IOException(Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_06));client=new MediaClient(c,()->node,e->{});Tasks.await(Wearable.getMessageClient(c).addListener(client),10,TimeUnit.SECONDS);JSONArray files=data.getJSONArray("items");
   for(int i=0;i<files.length();i++){if(isStopped()||Downloads.cancelled(c,job))return Result.success();JSONObject f=files.getJSONObject(i);if(Downloads.COMPLETE.equals(f.optString("phase")))continue;String id=f.getString("id"),name=f.optString("name");Downloads.update(c,job,id,Downloads.PREPARING,0,0,name);Downloads.notify(c,job);CompletableFuture<Uri> future=new CompletableFuture<>();AtomicLong shown=new AtomicLong();
    main.post(()->client.fetchMeta(id,true,(n,total)->{Downloads.update(c,job,id,Downloads.RUNNING,0,total,n);Downloads.notify(c,job);},done->{long now=SystemClock.elapsedRealtime();if(now-shown.get()>500){shown.set(now);Downloads.update(c,job,id,done<0?Downloads.PREPARING:Downloads.RUNNING,Math.max(0,done),0,null);Downloads.notify(c,job);}},future::complete,e->future.completeExceptionally(new IOException(e))));awaitCopy(future);Downloads.update(c,job,id,Downloads.COMPLETE,0,0,null);copied++;
   }
   Downloads.finish(c,job,Downloads.COMPLETE);if(copied>0)Controls.notice(c,String.format(java.util.Locale.getDefault(),Strings.tr(com.daniil.wristlens.shared.R.string.copy_downloaded_count),copied));return Result.success();
  }catch(Exception e){if(isStopped()||Downloads.cancelled(c,job))return Result.success();Downloads.finish(c,job,Downloads.ERROR);Controls.notice(c,Strings.tr(com.daniil.wristlens.shared.R.string.download_failed)+": "+(e.getCause()==null?e.getMessage():e.getCause().getMessage()));return Result.failure();}
  finally{MediaClient old=client;if(old!=null)main.post(old::close);}
 }
 private Uri awaitCopy(CompletableFuture<Uri> f)throws Exception{long deadline=SystemClock.elapsedRealtime()+TimeUnit.HOURS.toMillis(6);for(;;){if(isStopped()||Downloads.cancelled(getApplicationContext(),job))throw new CancellationException();try{return f.get(1,TimeUnit.SECONDS);}catch(TimeoutException e){if(SystemClock.elapsedRealtime()>deadline)throw e;}}}
 @Override public void onStopped(){MediaClient old=client;if(old!=null)main.post(old::close);if(job!=null&&!Downloads.cancelled(getApplicationContext(),job))Downloads.finish(getApplicationContext(),job,Downloads.QUEUED);}
}
